"""Domain and business logic exception definitions."""


class DomainError(Exception):
    """Base class for all domain errors."""

    def __init__(self, message: str):
        super().__init__(message)
        self.message = message


class DuplicateUTRError(DomainError):
    """Raised when a submitted UTR already exists in the system."""

    def __init__(self, utr: str):
        super().__init__(f"UTR '{utr}' has already been submitted and must be unique.")
        self.utr = utr


class InvalidSessionStateError(DomainError):
    """Raised when a state transition is not allowed for the payment session."""

    def __init__(self, current_status: str, action: str):
        super().__init__(
            f"Cannot perform action '{action}' on payment session with status '{current_status}'."
        )
        self.current_status = current_status
        self.action = action


class SessionNotFoundError(DomainError):
    """Raised when a payment session is not found."""

    def __init__(self, identifier: str):
        super().__init__(f"Payment session '{identifier}' was not found.")
        self.identifier = identifier


class SubmissionNotFoundError(DomainError):
    """Raised when a payment submission is not found."""

    def __init__(self, identifier: str):
        super().__init__(f"Payment submission '{identifier}' was not found.")
        self.identifier = identifier


class AuthenticationError(DomainError):
    """Raised when admin authentication fails (generic message to avoid enumeration)."""

    def __init__(self, message: str = "Invalid email or password."):
        super().__init__(message)


class InactiveAdminError(DomainError):
    """Raised when an admin account is deactivated."""

    def __init__(self, message: str = "Administrator account is deactivated."):
        super().__init__(message)


class InvalidRefreshTokenError(DomainError):
    """Raised when a refresh token is missing, expired, revoked, or malformed."""

    def __init__(self, message: str = "Invalid or expired session."):
        super().__init__(message)


class RefreshTokenReplayError(DomainError):
    """Raised when an already rotated refresh token is re-submitted."""

    def __init__(self, message: str = "Session has been invalidated due to token reuse."):
        super().__init__(message)

import React, { useEffect, useState } from 'react';
import { AuthProvider, useAuth } from '../context/AuthContext';
import { ProtectedRoute } from '../components/ProtectedRoute';
import { AdminLoginPage } from '../pages/AdminLoginPage';
import { AdminDashboardPage } from '../pages/AdminDashboardPage';
import { HealthStatus } from '../components/HealthStatus';
import { ShieldCheck, Layers, LogIn, LayoutDashboard } from 'lucide-react';

const AppContent: React.FC = () => {
  const [currentPath, setCurrentPath] = useState<string>(window.location.pathname);
  const { isAuthenticated } = useAuth();

  useEffect(() => {
    const handlePopState = () => {
      setCurrentPath(window.location.pathname);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const navigate = (path: string) => {
    window.history.pushState({}, '', path);
    setCurrentPath(path);
  };

  // Route matching helper
  const isPath = (target: string) => {
    const normalized = currentPath.endsWith('/') && currentPath.length > 1 ? currentPath.slice(0, -1) : currentPath;
    const targetNorm = target.endsWith('/') && target.length > 1 ? target.slice(0, -1) : target;
    return normalized === targetNorm || normalized === `${targetNorm}/`;
  };

  // 1. Admin Login Route (/upi/admin/login or /admin/login)
  if (isPath('/upi/admin/login') || isPath('/admin/login')) {
    return <AdminLoginPage onNavigate={navigate} />;
  }

  // 2. Admin Protected Area (/upi/admin or /admin)
  if (currentPath.startsWith('/upi/admin') || currentPath.startsWith('/admin')) {
    return (
      <ProtectedRoute onNavigate={navigate}>
        <AdminDashboardPage onNavigate={navigate} />
      </ProtectedRoute>
    );
  }

  // 3. Default Public Home (/upi/ or /)
  return (
    <div className="container">
      <header className="header">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
          <div className="badge">
            <ShieldCheck size={14} />
            Phase 3 — Auth & Core Infrastructure
          </div>
          <div>
            {isAuthenticated ? (
              <button
                onClick={() => navigate('/upi/admin')}
                className="btn btn-sm btn-primary"
                style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', cursor: 'pointer' }}
              >
                <LayoutDashboard size={14} />
                Admin Console
              </button>
            ) : (
              <button
                onClick={() => navigate('/upi/admin/login')}
                className="btn btn-sm btn-outline"
                style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', cursor: 'pointer' }}
              >
                <LogIn size={14} />
                Admin Sign In
              </button>
            )}
          </div>
        </div>
        <h1 className="title">Samagra UPI Automation</h1>
        <p className="subtitle">
          Foundational modular monolith stack: Vite + React, FastAPI, PostgreSQL, and Host Caddy.
        </p>
      </header>

      <main>
        <HealthStatus />

        <div className="card">
          <h2 className="card-title">
            <Layers size={20} color="#a78bfa" />
            Active Service Topologies & Namespaces
          </h2>
          <table className="meta-table">
            <tbody>
              <tr>
                <td className="meta-key">Host Reverse Proxy</td>
                <td className="meta-val">Host Caddy (Ports 80 / 443)</td>
              </tr>
              <tr>
                <td className="meta-key">Public URL Routes</td>
                <td className="meta-val">/upi/* (Frontend), /upi-api/* (Backend)</td>
              </tr>
              <tr>
                <td className="meta-key">Admin Portal Route</td>
                <td className="meta-val">
                  <a
                    href="/upi/admin/login"
                    onClick={(e) => {
                      e.preventDefault();
                      navigate('/upi/admin/login');
                    }}
                    style={{ color: '#818cf8', textDecoration: 'underline' }}
                  >
                    /upi/admin/login
                  </a>
                </td>
              </tr>
              <tr>
                <td className="meta-key">Frontend Host Port</td>
                <td className="meta-val">127.0.0.1:8080 (Prod) / 127.0.0.1:5173 (Dev)</td>
              </tr>
              <tr>
                <td className="meta-key">Backend Host Port</td>
                <td className="meta-val">127.0.0.1:8001 (FastAPI Container)</td>
              </tr>
              <tr>
                <td className="meta-key">PostgreSQL Storage</td>
                <td className="meta-val">./docker/postgres/data (Host Bind Mount)</td>
              </tr>
            </tbody>
          </table>
        </div>
      </main>

      <footer className="footer">
        <p>Samagra UPI Automation Platform &bull; Phase 3 Authenticated</p>
      </footer>
    </div>
  );
};

export const App: React.FC = () => {
  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
};

import React, { useState, useEffect } from 'react';
import { checkAppHealth, checkDatabaseHealth, HealthResponse, DbHealthResponse } from '../services/api';
import { RefreshCw, Server, XCircle, Clock } from 'lucide-react';
import { config } from '../core/config';

export const HealthStatus: React.FC = () => {
  const [appStatus, setAppStatus] = useState<'checking' | 'connected' | 'unavailable'>('checking');
  const [dbStatus, setDbStatus] = useState<'checking' | 'connected' | 'unavailable'>('checking');
  const [appData, setAppData] = useState<HealthResponse | null>(null);
  const [dbData, setDbData] = useState<DbHealthResponse | null>(null);
  const [lastChecked, setLastChecked] = useState<string | null>(null);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const performChecks = async () => {
    setIsRefreshing(true);
    setAppStatus('checking');
    setDbStatus('checking');

    try {
      const appRes = await checkAppHealth();
      setAppData(appRes);
      setAppStatus(appRes.status === 'ok' ? 'connected' : 'unavailable');
    } catch {
      setAppData(null);
      setAppStatus('unavailable');
    }

    try {
      const dbRes = await checkDatabaseHealth();
      setDbData(dbRes);
      setDbStatus(dbRes.status === 'ok' ? 'connected' : 'unavailable');
    } catch {
      setDbData(null);
      setDbStatus('unavailable');
    }

    setLastChecked(new Date().toLocaleTimeString());
    setIsRefreshing(false);
  };

  useEffect(() => {
    performChecks();
    const interval = setInterval(performChecks, 15000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="card">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <h2 className="card-title" style={{ margin: 0 }}>
          <Server size={20} color="#60a5fa" />
          Infrastructure Connectivity
        </h2>
        <button
          onClick={performChecks}
          disabled={isRefreshing}
          className="btn"
          title="Refresh connectivity status"
        >
          <RefreshCw size={14} className={isRefreshing ? 'pulse' : ''} />
          {isRefreshing ? 'Checking...' : 'Refresh'}
        </button>
      </div>

      <div className="status-grid">
        {/* Backend App Health */}
        <div className="status-item">
          <div className="status-info">
            <span className="status-label">FastAPI Backend</span>
            <span className="status-endpoint">/upi-api/v1/health</span>
          </div>
          <div>
            {appStatus === 'connected' && (
              <span className="status-pill connected">
                <span className="dot pulse" />
                Connected
              </span>
            )}
            {appStatus === 'unavailable' && (
              <span className="status-pill unavailable">
                <XCircle size={14} />
                Unavailable
              </span>
            )}
            {appStatus === 'checking' && (
              <span className="status-pill checking">
                <Clock size={14} />
                Checking
              </span>
            )}
          </div>
        </div>

        {/* PostgreSQL Database Health */}
        <div className="status-item">
          <div className="status-info">
            <span className="status-label">PostgreSQL Database</span>
            <span className="status-endpoint">/upi-api/v1/health/db</span>
          </div>
          <div>
            {dbStatus === 'connected' && (
              <span className="status-pill connected">
                <span className="dot pulse" />
                Connected
              </span>
            )}
            {dbStatus === 'unavailable' && (
              <span className="status-pill unavailable">
                <XCircle size={14} />
                Unavailable
              </span>
            )}
            {dbStatus === 'checking' && (
              <span className="status-pill checking">
                <Clock size={14} />
                Checking
              </span>
            )}
          </div>
        </div>
      </div>

      {/* Connection Metadata */}
      <table className="meta-table">
        <tbody>
          <tr>
            <td className="meta-key">Frontend Base Path</td>
            <td className="meta-val">{config.basePath}</td>
          </tr>
          <tr>
            <td className="meta-key">API Base URL</td>
            <td className="meta-val">{config.apiBaseUrl}</td>
          </tr>
          <tr>
            <td className="meta-key">Backend Reported App</td>
            <td className="meta-val">{appData?.app || '—'}</td>
          </tr>
          <tr>
            <td className="meta-key">Backend Environment</td>
            <td className="meta-val">{appData?.env || '—'}</td>
          </tr>
          <tr>
            <td className="meta-key">Database Status</td>
            <td className="meta-val">{dbData?.database || '—'}</td>
          </tr>
          <tr>
            <td className="meta-key">Last Inspected</td>
            <td className="meta-val">{lastChecked || 'Pending initial check'}</td>
          </tr>
        </tbody>
      </table>
    </div>
  );
};

/**
 * Protected route guard requiring active authenticated administrator.
 */

import React, { useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { ShieldAlert, Loader2 } from 'lucide-react';

interface ProtectedRouteProps {
  children: React.ReactNode;
  onNavigate?: (path: string) => void;
}

export const ProtectedRoute: React.FC<ProtectedRouteProps> = ({ children, onNavigate }) => {
  const { isAuthenticated, isLoading } = useAuth();

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      if (onNavigate) {
        onNavigate('/upi/admin/login');
      } else {
        window.history.pushState({}, '', '/upi/admin/login');
        window.dispatchEvent(new PopStateEvent('popstate'));
      }
    }
  }, [isLoading, isAuthenticated, onNavigate]);

  if (isLoading) {
    return (
      <div className="card loading-card" style={{ textAlign: 'center', padding: '3rem 1rem' }}>
        <Loader2 className="spinner" size={36} color="#818cf8" />
        <p style={{ marginTop: '1rem', color: '#94a3b8' }}>Verifying administrator session...</p>
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
      <div className="card" style={{ textAlign: 'center', padding: '2rem 1rem' }}>
        <ShieldAlert size={40} color="#f87171" style={{ margin: '0 auto 1rem' }} />
        <h2 style={{ color: '#f87171', fontSize: '1.25rem', marginBottom: '0.5rem' }}>
          Authentication Required
        </h2>
        <p style={{ color: '#94a3b8', fontSize: '0.875rem' }}>
          Redirecting to administrator login...
        </p>
      </div>
    );
  }

  return <>{children}</>;
};

/**
 * Authentication Context maintaining in-memory access token, admin profile,
 * and automatic session restoration on app initialization.
 */

import React, { createContext, useContext, useEffect, useState } from 'react';
import { AdminUser, AuthState } from '../types/auth';
import { getMeApi, loginApi, logoutAllApi, logoutApi, refreshApi } from '../services/apiClient';

interface AuthContextType extends AuthState {
  login: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  logoutAll: () => Promise<void>;
  refreshSession: () => Promise<boolean>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [admin, setAdmin] = useState<AdminUser | null>(null);
  const [accessToken, setAccessTokenState] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  // Function to refresh session from HttpOnly cookie
  const refreshSession = async (): Promise<boolean> => {
    try {
      const response = await refreshApi();
      if (response && response.access_token) {
        setAccessTokenState(response.access_token);
        // Also fetch fresh user profile to ensure active status
        const profile = await getMeApi();
        setAdmin(profile);
        return true;
      }
      setAdmin(null);
      setAccessTokenState(null);
      return false;
    } catch {
      setAdmin(null);
      setAccessTokenState(null);
      return false;
    }
  };

  // Restore session from HttpOnly refresh cookie on application mount
  useEffect(() => {
    let isMounted = true;

    async function initAuth() {
      await refreshSession();
      if (isMounted) {
        setIsLoading(false);
      }
    }

    initAuth();

    return () => {
      isMounted = false;
    };
  }, []);

  const login = async (email: string, password: string): Promise<void> => {
    setIsLoading(true);
    try {
      const response = await loginApi(email, password);
      setAccessTokenState(response.access_token);
      setAdmin(response.admin);
    } finally {
      setIsLoading(false);
    }
  };

  const logout = async (): Promise<void> => {
    setIsLoading(true);
    try {
      await logoutApi();
    } finally {
      setAdmin(null);
      setAccessTokenState(null);
      setIsLoading(false);
    }
  };

  const logoutAll = async (): Promise<void> => {
    setIsLoading(true);
    try {
      await logoutAllApi();
    } finally {
      setAdmin(null);
      setAccessTokenState(null);
      setIsLoading(false);
    }
  };

  const value: AuthContextType = {
    admin,
    accessToken,
    isAuthenticated: !!admin && !!accessToken,
    isLoading,
    login,
    logout,
    logoutAll,
    refreshSession,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export function useAuth(): AuthContextType {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

